66	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
67		parts := strings.Split(s, "/")
68		if len(parts) != 3 {
69			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
70		}
71		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
72		if err := id.Validate(); err != nil {
73			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
74		}
75		return id, nil
76	}
